def maxOperations(s: str) -> int:
    ans = 0      # total number of moves
    cnt = 0      # count of 1s so far
    n = len(s)
    for i, c in enumerate(s):
        if c == '1':
            cnt += 1
        elif i > 0 and s[i-1] == '1':
            ans += cnt
    return ans
